import{_ as t,o as a,c as s,ae as r}from"./chunks/framework.RRduUuAx.js";const p=JSON.parse('{"title":"Customer Validation Pack — 1000 Concurrent Sessions","description":"","frontmatter":{},"headers":[],"relativePath":"cvp/README.md","filePath":"cvp/README.md"}'),n={name:"cvp/README.md"};function o(d,e,i,c,l,h){return a(),s("div",null,[...e[0]||(e[0]=[r(`<h1 id="customer-validation-pack-—-1000-concurrent-sessions" tabindex="-1">Customer Validation Pack — 1000 Concurrent Sessions <a class="header-anchor" href="#customer-validation-pack-—-1000-concurrent-sessions" aria-label="Permalink to &quot;Customer Validation Pack — 1000 Concurrent Sessions&quot;">​</a></h1><p><strong>Claim (Q7=A):</strong> HeliosLab supports 1000 concurrent live sessions.</p><p><strong>Status:</strong> Verified. See <code>cvp-1000.json</code> for the raw run.</p><hr><h2 id="what-is-measured" tabindex="-1">What is measured <a class="header-anchor" href="#what-is-measured" aria-label="Permalink to &quot;What is measured&quot;">​</a></h2><p>The committed <code>cvp-1000.json</code> records the outcome of a 1000-lane run captured on a developer workstation. The harness that produced it materialises real child processes through <code>PtyManager</code> and binds each stdout into a renderer surface through <code>StreamBindingManager</code>, via <code>VerticalSliceDriver</code>.</p><h2 id="results-1000-lanes-cold-burst" tabindex="-1">Results (1000 lanes, cold burst) <a class="header-anchor" href="#results-1000-lanes-cold-burst" aria-label="Permalink to &quot;Results (1000 lanes, cold burst)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Metric</th><th>Value</th></tr></thead><tbody><tr><td>Lanes bound</td><td>1000 / 1000</td></tr><tr><td>Setup</td><td>0.76 ms</td></tr><tr><td>Spawn + bind (cold burst)</td><td>98.5 s</td></tr><tr><td>Per-lane p50</td><td>98.4 s</td></tr><tr><td>Per-lane p99</td><td>98.5 s</td></tr><tr><td>Cleanup</td><td>0.60 s</td></tr><tr><td>Throughput</td><td>10.2 lanes/s</td></tr><tr><td>Memory delta (post-cleanup)</td><td>65 MB</td></tr><tr><td>Peak memory above baseline</td><td>63 MB</td></tr><tr><td><strong>Overall</strong></td><td><strong>PASS</strong></td></tr></tbody></table><p>Run-to-run variance on that workstation ranged 57-99 s for the cold burst (throughput 10-17 lanes/s), depending on background load.</p><h2 id="what-the-numbers-mean" tabindex="-1">What the numbers mean <a class="header-anchor" href="#what-the-numbers-mean" aria-label="Permalink to &quot;What the numbers mean&quot;">​</a></h2><p><strong>Capacity is the claim, and it holds.</strong> All 1000 lanes reached a renderer surface. Memory stayed flat at ~65 MB for the whole fleet, and cleanup returned within a second. There is no per-lane leak that scales with count.</p><p><strong>Cold-burst latency is bounded by the burst, not by any single lane.</strong> All 1000 lanes are requested at once, so each lane&#39;s wall-clock wait includes sharing the machine with the other 999 spawns. Per-lane p50 equaling the burst duration is the expected shape of a cold burst, not a defect. Real usage creates lanes incrementally, where per-lane latency is a fraction of the burst time.</p><p><strong>Thresholds scale with count.</strong> The harness bounds a cold burst at 150 ms per lane (150 s for 1000 lanes) rather than a fixed constant, because a fixed constant would either be meaningless for small counts or arbitrarily tight for large ones.</p><h2 id="reproduce" tabindex="-1">Reproduce <a class="header-anchor" href="#reproduce" aria-label="Permalink to &quot;Reproduce&quot;">​</a></h2><p>The harness (<code>apps/runtime/tests/cvp/cvp-harness.ts</code>) lives on the <code>wbs/terminal-slice</code> branch today. It will be cherry-picked onto <code>main</code> once the terminal-first work (<code>VerticalSliceDriver</code>, <code>RecordingRendererAdapter</code>) lands:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># From the wbs/terminal-slice branch</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apps/runtime/tests/cvp/cvp-harness.ts</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --count=1000</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --output=docs/cvp/cvp-1000.json</span></span></code></pre></div><p>The scaling regression suite (25 / 100 / 250 lanes) is opt-in via <code>CVP_SCALING=1</code> because materialising hundreds of live PTYs in one process starves anything running beside it.</p><h2 id="thresholds" tabindex="-1">Thresholds <a class="header-anchor" href="#thresholds" aria-label="Permalink to &quot;Thresholds&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Metric</th><th>Bound</th></tr></thead><tbody><tr><td>Spawn p99</td><td><code>count * 150 ms</code></td></tr><tr><td>Total</td><td><code>count * 150 ms + 60 s</code></td></tr><tr><td>Cleanup</td><td><code>count * 20 ms + 5 s</code></td></tr><tr><td>Memory delta</td><td>200 MB</td></tr></tbody></table><h2 id="ci-gate" tabindex="-1">CI gate <a class="header-anchor" href="#ci-gate" aria-label="Permalink to &quot;CI gate&quot;">​</a></h2><p>The committed <code>docs/cvp/cvp-1000.json</code> is validated on every pull request via the <code>cvp-evidence.yml</code> workflow. The gate verifies the schema (<code>helios.cvp.v1</code>), the <code>overallPass</code> flag, every <code>pass.*</code> flag, and that each measurement is within the bounds declared in the report&#39;s own <code>thresholds</code> block. When the JSON file is missing, the gate skips (validator alone cannot tell &quot;no evidence yet&quot; from &quot;evidence was deleted&quot;); once present, the gate enforces every constraint. The harness itself stays opt-in via <code>CVP_SCALING=1</code> because materialising 1000 live PTYs is expensive on shared runners.</p><h2 id="files" tabindex="-1">Files <a class="header-anchor" href="#files" aria-label="Permalink to &quot;Files&quot;">​</a></h2><ul><li><code>docs/cvp/cvp-1000.json</code> — raw evidence for the 1000-lane run</li><li><code>apps/runtime/tests/cvp/cvp-harness.ts</code> — the harness (terminal-slice)</li><li><code>apps/runtime/tests/cvp/cvp-scaling.test.ts</code> — regression suite (terminal-slice)</li><li><code>apps/runtime/tests/cvp/run-scaling.ts</code> — scaling orchestrator (terminal-slice)</li></ul>`,23)])])}const m=t(n,[["render",o]]);export{p as __pageData,m as default};
